query:
SELECT 'NAWAH/MARC/MEDSOL workshops' as type, workshop_choice, workshop_payment_status, COUNT(*) as count, SUM(CASE WHEN workshop_invoice_url IS NOT NULL AND workshop_invoice_url != '' THEN 1 ELSE 0 END) as has_invoice FROM registrations WHERE wants_workshop = 1 GROUP BY workshop_choice, workshop_payment_status
UNION ALL
SELECT 'Ext workshops (pre/post)' as type, ext_workshop_choice, ext_workshop_payment_status, COUNT(*) as count, SUM(CASE WHEN ext_workshop_invoice_url IS NOT NULL AND ext_workshop_invoice_url != '' THEN 1 ELSE 0 END) as has_invoice FROM registrations WHERE wants_ext_workshop = 1 GROUP BY ext_workshop_choice, ext_workshop_payment_status;
